// The islamic-umalqura calendar: ICU's Umm al-Qura month table for AH 1300..1600
// (calendar_islamic_umalqura_data.inc, generated by tools/temporal/gen-calendars.mjs), and the islamic-civil
// arithmetic outside it, as ICU does. The table's first and last days meet the civil arithmetic exactly.
#include <cstdint>
#include <vector>

#include "builtins/temporal/calendar_systems.h"

namespace snowman::temporal {

namespace {
#include "builtins/temporal/calendar_islamic_umalqura_data.inc"

constexpr size_t kTableYears = sizeof(kUmalquraYears) / sizeof(kUmalquraYears[0]);
static_assert(kTableYears == size_t(kUmalquraLastYear - kUmalquraFirstYear + 1));

int64_t floorDiv(int64_t a, int64_t b) { return a / b - ((a % b != 0) && ((a < 0) != (b < 0))); }

// The tabular islamic-civil calendar: 1 Muharram 1 AH is 622-07-16 (Julian), epoch day -492148.
constexpr int64_t kCivilEpoch = -492148;
int64_t civilYearStart(int64_t year) { return kCivilEpoch + (year - 1) * 354 + floorDiv(3 + 11 * year, 30); }
bool civilLeapYear(int64_t year) { return ((14 + 11 * year) % 30 + 30) % 30 < 11; }
int32_t civilDaysInMonth(int64_t year, int32_t month) {
  if (month == 12) return civilLeapYear(year) ? 30 : 29;
  return month % 2 == 1 ? 30 : 29;
}

const EraRow kEras[] = {
    {u"ah", nullptr, EraRow::Kind::Epoch, 0},
    {u"bh", nullptr, EraRow::Kind::Negative, 0},
};

class UmalquraCalendar final : public CalendarSystem {
 public:
  UmalquraCalendar() {
    int64_t start = kUmalquraFirstNewYear;
    for (uint16_t bits : kUmalquraYears) {
      starts_.push_back(start);
      for (int32_t m = 1; m <= 12; m++) start += tableMonthLength(bits, m);
    }
    starts_.push_back(start);
  }

  Date fromEpochDays(int64_t epochDays) const override {
    int64_t year;
    if (epochDays >= starts_.front() && epochDays < starts_.back()) {
      size_t lo = 0, hi = kTableYears - 1;
      while (lo < hi) {
        size_t mid = (lo + hi + 1) / 2;
        if (starts_[mid] <= epochDays) lo = mid;
        else hi = mid - 1;
      }
      year = kUmalquraFirstYear + int64_t(lo);
    } else {
      // 10631 days per 30 years; adjust the estimate to the year that contains epochDays.
      year = floorDiv((epochDays - kCivilEpoch) * 30 + 10646, 10631);
      while (yearStart(year) > epochDays) year--;
      while (yearStart(year + 1) <= epochDays) year++;
    }
    int32_t day = int32_t(epochDays - yearStart(year));
    int32_t month = 1;
    for (; day >= daysInMonth(year, month); month++) day -= daysInMonth(year, month);
    return {year, month, day + 1};
  }

  int64_t toEpochDays(int64_t year, int32_t month, int32_t day) const override {
    int64_t days = yearStart(year);
    for (int32_t m = 1; m < month; m++) days += daysInMonth(year, m);
    return days + day - 1;
  }

  int32_t monthsInYear(int64_t) const override { return 12; }
  int32_t daysInMonth(int64_t year, int32_t month) const override {
    if (inTable(year)) return tableMonthLength(kUmalquraYears[size_t(year - kUmalquraFirstYear)], month);
    return civilDaysInMonth(year, month);
  }
  bool inLeapYear(int64_t year) const override {
    if (!inTable(year)) return civilLeapYear(year);
    return yearStart(year + 1) - yearStart(year) == 355;
  }
  int32_t maxDaysInMonthCode(MonthCodeParts) const override { return 30; }
  std::span<const EraRow> eras() const override { return kEras; }

 private:
  static bool inTable(int64_t year) { return year >= kUmalquraFirstYear && year <= kUmalquraLastYear; }
  static int32_t tableMonthLength(uint16_t bits, int32_t month) { return bits & (1u << (month - 1)) ? 30 : 29; }
  int64_t yearStart(int64_t year) const {
    if (year >= kUmalquraFirstYear && year <= kUmalquraLastYear + 1) return starts_[size_t(year - kUmalquraFirstYear)];
    return civilYearStart(year);
  }

  std::vector<int64_t> starts_;  // starts_[i]: 1 Muharram of kUmalquraFirstYear + i; one past the end too
};

const UmalquraCalendar kUmalqura;
}  // namespace

const CalendarSystem* IslamicUmalquraCalendarSystem() { return &kUmalqura; }

}  // namespace snowman::temporal
